(function(){
  const moves={
    impacto:{name:'Impacto',type:'normal',power:8,pp:30},folha:{name:'Folha-lâmina',type:'grass',power:12,pp:20},brasa:{name:'Brasa viva',type:'fire',power:12,pp:20},onda:{name:'Bolha d’água',type:'water',power:12,pp:20},faísca:{name:'Faísca',type:'electric',power:12,pp:20},sombra:{name:'Sopro sombrio',type:'shadow',power:14,pp:15},cura:{name:'Pólen curativo',type:'fairy',power:-12,pp:10}
  };
  const species={
    lumito:{name:'Lumito',type:'fairy',color:'#f9c86a',accent:'#fff2a1',shape:'fox',moves:['impacto','faísca','cura'],desc:'Uma raposinha luminosa que guia viajantes na neblina.'},
    brotling:{name:'Brotling',type:'grass',color:'#63cf91',accent:'#b5f484',shape:'sprout',moves:['impacto','folha'],desc:'Uma criatura-broto que dança quando a chuva chega.'},
    brasalto:{name:'Brasalto',type:'fire',color:'#f07858',accent:'#ffd071',shape:'lizard',moves:['impacto','brasa'],desc:'Pequeno lagarto que guarda uma brasa no peito.'},
    gotinha:{name:'Gotinha',type:'water',color:'#5dbbe8',accent:'#b5edff',shape:'blob',moves:['impacto','onda'],desc:'Uma gota curiosa que salta de poça em poça.'},
    noturno:{name:'Noturno',type:'shadow',color:'#846ed4',accent:'#c4afff',shape:'owl',moves:['impacto','sombra'],desc:'Uma coruja misteriosa, mas muito amigável.'},
    pedrino:{name:'Pedrino',type:'normal',color:'#a9a9b5',accent:'#e5d4bd',shape:'rock',moves:['impacto','folha'],desc:'Um montinho de pedras com um coração enorme.'}
  };
  window.NevData={moves,species,types:{grass:'#59c47a',fire:'#f2764a',water:'#52a7e8',electric:'#f2c94c',shadow:'#9a7fe0',fairy:'#f08fc0',normal:'#b8b8c8'},items:[{id:'potion',name:'Poção',icon:'🧪',price:18,desc:'Recupera 20 PV da criatura líder.'},{id:'revive',name:'Reviver',icon:'✨',price:35,desc:'Revive a criatura líder com metade dos PV.'},{id:'orb',name:'Orbe de névoa',icon:'🔮',price:24,desc:'Ajuda a acolher uma criatura selvagem.'}]};
})();

(function(){
  function draw(canvas,id,scale=1){if(!canvas)return; const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height; c.clearRect(0,0,w,h); c.save(); c.translate(w/2,h*.57); c.scale(scale,scale); c.lineJoin='round'; c.lineCap='round';
    const s=window.NevData.species[id]||window.NevData.species.lumito, fill=s.color, hi=s.accent;
    c.fillStyle='rgba(8,5,20,.22)';c.beginPath();c.ellipse(0,70,62,15,0,0,Math.PI*2);c.fill();
    const shape=s.shape;
    if(shape==='fox'){
      c.fillStyle=fill;c.beginPath();c.moveTo(-44,-36);c.lineTo(-57,-95);c.quadraticCurveTo(-31,-83,-21,-58);c.quadraticCurveTo(8,-80,25,-57);c.lineTo(48,-84);c.lineTo(45,-28);c.quadraticCurveTo(67,17,38,47);c.quadraticCurveTo(2,75,-40,47);c.quadraticCurveTo(-69,13,-44,-36);c.fill();
      c.fillStyle=hi;c.beginPath();c.ellipse(3,14,39,32,0,0,Math.PI*2);c.fill();c.fillStyle='#332346';for(const x of [-15,15]){c.beginPath();c.ellipse(x,-8,4,7,0,0,Math.PI*2);c.fill()}c.beginPath();c.arc(0,9,3,0,7);c.fill();
    } else if(shape==='sprout'){
      c.fillStyle=fill;c.beginPath();c.ellipse(0,8,56,59,0,0,Math.PI*2);c.fill();c.fillStyle=hi;c.beginPath();c.ellipse(0,25,32,29,0,0,Math.PI*2);c.fill();c.strokeStyle='#287a59';c.lineWidth=7;c.beginPath();c.moveTo(0,-38);c.quadraticCurveTo(-9,-75,-34,-76);c.quadraticCurveTo(-36,-47,-3,-39);c.moveTo(2,-40);c.quadraticCurveTo(13,-78,40,-70);c.quadraticCurveTo(37,-45,2,-40);c.stroke();c.fillStyle='#26344a';for(const x of [-17,17]){c.beginPath();c.arc(x,3,4,0,7);c.fill()}
    } else if(shape==='lizard'){
      c.fillStyle=fill;c.beginPath();c.ellipse(0,4,54,49,-.08,0,7);c.moveTo(38,23);c.quadraticCurveTo(86,12,74,-27);c.quadraticCurveTo(109,17,60,48);c.fill();c.fillStyle=hi;c.beginPath();c.ellipse(-4,18,30,26,0,0,7);c.fill();c.fillStyle='#32253a';for(const x of [-20,17]){c.beginPath();c.arc(x,-9,4,0,7);c.fill()}c.fillStyle='#ffae52';c.beginPath();c.moveTo(-4,-53);c.quadraticCurveTo(-21,-74,-5,-88);c.quadraticCurveTo(2,-69,10,-82);c.quadraticCurveTo(27,-60,7,-51);c.fill();
    } else if(shape==='blob'){
      c.fillStyle=fill;c.beginPath();c.moveTo(-55,25);c.quadraticCurveTo(-71,-20,-34,-43);c.quadraticCurveTo(-10,-78,16,-45);c.quadraticCurveTo(65,-38,55,17);c.quadraticCurveTo(48,64,0,58);c.quadraticCurveTo(-47,64,-55,25);c.fill();c.fillStyle=hi;c.beginPath();c.ellipse(-18,-16,11,18,-.6,0,7);c.fill();c.fillStyle='#23415b';for(const x of [-17,17]){c.beginPath();c.arc(x,5,4,0,7);c.fill()}
    } else if(shape==='owl'){
      c.fillStyle=fill;c.beginPath();c.moveTo(-48,-14);c.lineTo(-52,-65);c.lineTo(-15,-46);c.quadraticCurveTo(0,-58,17,-46);c.lineTo(51,-65);c.lineTo(47,-7);c.quadraticCurveTo(68,45,0,57);c.quadraticCurveTo(-64,47,-48,-14);c.fill();c.fillStyle=hi;for(const x of [-20,20]){c.beginPath();c.arc(x,-5,17,0,7);c.fill();c.fillStyle='#352742';c.beginPath();c.arc(x,-5,6,0,7);c.fill();c.fillStyle=hi}c.fillStyle='#ffbf66';c.beginPath();c.moveTo(-6,13);c.lineTo(7,13);c.lineTo(0,24);c.fill();
    } else {
      c.fillStyle=fill;c.beginPath();c.moveTo(-48,39);c.lineTo(-55,-5);c.lineTo(-25,-56);c.lineTo(1,-46);c.lineTo(24,-66);c.lineTo(53,-22);c.lineTo(46,34);c.lineTo(18,55);c.lineTo(-23,52);c.fill();c.fillStyle=hi;c.beginPath();c.ellipse(0,25,24,17,0,0,7);c.fill();c.fillStyle='#353140';for(const x of [-17,17]){c.beginPath();c.arc(x,0,4,0,7);c.fill()}
    }
    c.strokeStyle='rgba(45,34,65,.4)';c.lineWidth=3;c.beginPath();c.moveTo(-21,45);c.lineTo(-24,57);c.moveTo(22,45);c.lineTo(24,57);c.stroke();c.restore();
  }
  function scene(canvas){if(!canvas)return;let c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);let g=c.createLinearGradient(0,0,0,h);g.addColorStop(0,'#2b2050');g.addColorStop(1,'#101327');c.fillStyle=g;c.fillRect(0,0,w,h);for(let i=0;i<34;i++){let x=(i*173)%w,y=(i*97)%h;c.fillStyle=`rgba(190,220,255,${.15+(i%5)*.09})`;c.beginPath();c.arc(x,y,1+i%3,0,7);c.fill()}c.fillStyle='#192e34';for(let i=0;i<12;i++){let x=i*w/10-20; c.beginPath();c.moveTo(x,h*.72);c.lineTo(x+45,h*.46-(i%3)*20);c.lineTo(x+90,h*.72);c.fill()}c.fillStyle='#31674c';c.beginPath();c.ellipse(w*.5,h*1.1,w*.68,h*.38,0,0,7);c.fill();}
  window.NevSprites={draw,scene};
})();

(function(){
 const W=window, D=W.NevData;let canvas,ctx,raf=0,last=0,player={x:0,y:0,dir:1,step:0},keys={},joy={x:0,y:0},actors=[],onAction=()=>{},onEncounter=()=>{},active=true,cam={x:0,y:0};
 function resize(){const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(innerWidth*d);canvas.height=Math.floor(innerHeight*d);ctx.setTransform(d,0,0,d,0,0)}
 function init(opts){canvas=document.getElementById('world');ctx=canvas.getContext('2d');resize();addEventListener('resize',resize);player.x=innerWidth*.5;player.y=innerHeight*.63;actors=[{id:'iris',name:'Professora Íris',x:innerWidth*.5-55,y:innerHeight*.36,kind:'person',color:'#b898ff',label:'Íris'},{id:'loja',name:'Dona Lume',x:innerWidth*.72,y:innerHeight*.45,kind:'person',color:'#f5ad79',label:'Loja'},{id:'guia',name:'Guardião',x:innerWidth*.29,y:innerHeight*.43,kind:'person',color:'#89d9be',label:'Guia'}];onAction=opts.action;onEncounter=opts.encounter;requestAnimationFrame(frame)}
 function setActive(v){active=v}
 function setPosition(x,y){player.x=x;player.y=y}
 function getPlayer(){return {...player}}
 function setJoy(x,y){joy={x,y}}
 function interact(){let nearest=null,dist=100;for(let a of actors){let d=Math.hypot(a.x-player.x,a.y-player.y);if(d<dist){dist=d;nearest=a}}if(nearest){onAction(nearest.id);return true}return false}
 function frame(t){raf=requestAnimationFrame(frame);let dt=Math.min(.04,(t-last)/1000||0);last=t;if(active){let dx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0)+joy.x,dy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0)+joy.y,len=Math.hypot(dx,dy);if(len>.15){dx/=Math.max(1,len);dy/=Math.max(1,len);let speed=165;let ox=player.x,oy=player.y;player.x=Math.max(26,Math.min(innerWidth-26,player.x+dx*speed*dt));player.y=Math.max(innerHeight*.23,Math.min(innerHeight-75,player.y+dy*speed*dt));player.dir=dx<-.1?-1:dx>.1?1:player.dir;if(Math.hypot(player.x-ox,player.y-oy)>1){player.step+=dt*12;if(Math.random()<dt*1.6)W.NevAudio.play('step');if(player.step>10){player.step=0;if(player.y>innerHeight*.60&&Math.random()<.08)onEncounter()}}}}
    render(t)}
 function render(t){let w=innerWidth,h=innerHeight;if(!ctx)return;let g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#241c42');g.addColorStop(.42,'#33455a');g.addColorStop(1,'#426748');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
    // layered hills, path and meadow
    ctx.fillStyle='#28394d';ctx.beginPath();ctx.moveTo(0,h*.48);for(let x=0;x<=w+40;x+=40)ctx.lineTo(x,h*.39+Math.sin(x*.012)*24);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.fillStyle='#3c674e';ctx.beginPath();ctx.moveTo(0,h*.62);for(let x=0;x<=w+40;x+=30)ctx.lineTo(x,h*.57+Math.sin(x*.02+1)*18);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();
    ctx.fillStyle='#9b8a69';ctx.beginPath();ctx.moveTo(w*.37,h);ctx.quadraticCurveTo(w*.48,h*.68,w*.49,h*.46);ctx.quadraticCurveTo(w*.53,h*.42,w*.56,h*.47);ctx.quadraticCurveTo(w*.56,h*.7,w*.66,h);ctx.fill();ctx.fillStyle='#b4a07b';ctx.beginPath();ctx.moveTo(w*.43,h);ctx.quadraticCurveTo(w*.5,h*.65,w*.51,h*.48);ctx.quadraticCurveTo(w*.53,h*.72,w*.60,h);ctx.fill();
    // village houses
    for(const [x,y,col] of [[.08,.40,'#d78678'],[.82,.38,'#dca95e'],[.15,.51,'#8a85bc']]){let bx=x*w,by=y*h,bw=Math.min(100,w*.18),bh=Math.min(85,h*.17);ctx.fillStyle='#49384b';ctx.fillRect(bx,by,bw,bh);ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(bx-8,by+12);ctx.lineTo(bx+bw/2,by-bh*.52);ctx.lineTo(bx+bw+8,by+12);ctx.fill();ctx.fillStyle='#ffd994';ctx.fillRect(bx+bw*.14,by+bh*.27,bw*.2,bh*.23);ctx.fillRect(bx+bw*.65,by+bh*.27,bw*.2,bh*.23);ctx.fillStyle='#654739';ctx.fillRect(bx+bw*.42,by+bh*.53,bw*.2,bh*.47)}
    // flowers & grass
    for(let i=0;i<100;i++){let x=(i*137)%w,y=h*.56+(i*79%(Math.max(1,h*.43)));ctx.fillStyle=i%4?'rgba(130,205,120,.45)':'rgba(242,208,126,.75)';ctx.beginPath();ctx.arc(x,y,1.3+i%3,0,7);ctx.fill()}
    actors.forEach(a=>drawPerson(a.x,a.y,a.color,a.label,false));drawPerson(player.x,player.y,'#72ddbd','',true);
    // atmospheric motes
    for(let i=0;i<18;i++){let x=(i*191+t*.008)%w,y=(i*89+t*.012)%h;ctx.fillStyle='rgba(220,237,255,.23)';ctx.beginPath();ctx.arc(x,y,2,0,7);ctx.fill()}
    document.getElementById('interactHint').classList.toggle('hidden',!actors.some(a=>Math.hypot(a.x-player.x,a.y-player.y)<100));
 }
 function drawPerson(x,y,color,label,isPlayer){let bob=Math.sin(performance.now()*.003+(x))*2;ctx.fillStyle='rgba(0,0,0,.24)';ctx.beginPath();ctx.ellipse(x,y+14,18,6,0,0,7);ctx.fill();ctx.fillStyle='#382a49';ctx.fillRect(x-11,y-3+bob,22,18);ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x-12,y-26+bob,24,28,8);ctx.fill();ctx.fillStyle='#f0c4a4';ctx.beginPath();ctx.arc(x,y-32+bob,10,0,7);ctx.fill();ctx.fillStyle=isPlayer?'#2d2347':'#473752';ctx.beginPath();ctx.arc(x,y-36+bob,11,Math.PI,0);ctx.fill();if(label){ctx.font='bold 11px system-ui';let width=ctx.measureText(label).width+14;ctx.fillStyle='rgba(20,15,34,.76)';ctx.beginPath();ctx.roundRect(x-width/2,y-61,width,18,7);ctx.fill();ctx.fillStyle='#fff';ctx.textAlign='center';ctx.fillText(label,x,y-48)}}
 window.NevWorld={init,setActive,setJoy,getPlayer,setPosition,interact};
})();

(function(){const $=s=>document.querySelector(s),D=window.NevData;let dialog=null,di=0,lines=[],choiceCb=null,tab='team',game=null;
 function show(id){$(id).classList.remove('hidden')}function hide(id){$(id).classList.add('hidden')}function toast(text){let el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('show'),2100)}
 function say(name,text,done){const arr=Array.isArray(text)?text:[text];lines=arr;di=0;dialog=done||null;choiceCb=null;$('#dlgName').textContent=name;$('#dlgChoices').classList.add('hidden');$('#dlgNext').classList.remove('hidden');show('#dialogue');paintLine()}
 function paintLine(){ $('#dlgText').textContent=lines[di]||'';$('#dlgNext').textContent=di<lines.length-1?'▾ toque para continuar':'▾ toque para fechar'; }
 function advance(){if($('#dialogue').classList.contains('hidden'))return;if(choiceCb)return;if(di<lines.length-1){di++;paintLine()}else{hide('#dialogue');let cb=dialog;dialog=null;if(cb)cb()}}
 function choices(name,text,opts){lines=[text];di=0;dialog=null;choiceCb=opts;$('#dlgName').textContent=name;$('#dlgText').textContent=text;$('#dlgNext').classList.add('hidden');const box=$('#dlgChoices');box.innerHTML='';opts.forEach(o=>{let b=document.createElement('button');b.className='choice';b.textContent=o.label;b.onclick=()=>{hide('#dialogue');box.classList.add('hidden');$('#dlgNext').classList.remove('hidden');choiceCb=null;o.action()};box.appendChild(b)});box.classList.remove('hidden');show('#dialogue')}
 function renderMenu(g){game=g;const body=$('#menuBody');if(tab==='team'){body.innerHTML=g.team.map((m,i)=>{let s=D.species[m.id],pct=Math.max(0,m.hp/m.maxHp*100);return `<div class="party-row ${i===g.lead?'lead':''}"><div class="party-thumb"><canvas data-mon="${m.id}" width="80" height="80"></canvas></div><div class="party-main"><div class="party-name">${s.name}<span class="lvl">Nv. ${m.level}</span><span class="type-chip" style="background:${D.types[s.type]}">${s.type}</span></div><div class="hp-track"><div class="hp-fill ${pct<25?'low':pct<50?'mid':''}" style="width:${pct}%"></div></div><div class="party-hp"><span>PV</span><span>${m.hp}/${m.maxHp}</span></div></div><div class="party-btns">${i!==g.lead?`<button class="mini-btn" data-lead="${i}">Líder</button>`:''}</div></div>`}).join('')||'<p>Seu time está vazio.</p>';body.querySelectorAll('canvas[data-mon]').forEach(c=>W.NevSprites.draw(c,c.dataset.mon));body.querySelectorAll('[data-lead]').forEach(b=>b.onclick=()=>{g.lead=+b.dataset.lead;renderMenu(g);toast('Líder do time alterado.')})}
    else if(tab==='bag'){body.innerHTML=D.items.map(it=>`<div class="item-row"><div class="item-ico">${it.icon}</div><div class="item-main"><div class="item-name">${it.name}</div><div class="item-desc">${it.desc}</div></div><div class="item-count">×${g.bag[it.id]||0}</div><button class="mini-btn" data-use="${it.id}" ${(g.bag[it.id]||0)<=0?'disabled':''}>Usar</button></div>`).join('');body.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{if(g.useItem(b.dataset.use)){renderMenu(g)}else toast('Não é possível usar agora.')})}
    else{body.innerHTML=`<div class="info-card"><h3>Uma jornada entre a névoa</h3><p>${g.story||'Ajude a Professora Íris a descobrir por que a névoa mágica está crescendo. Encontre criaturas, explore e reúna os três cristais.'}</p><div class="crystal-row">${['Aurora','Bruma','Crepúsculo'].map((n,i)=>`<div class="crystal-slot ${g.crystals[i]?'on':''}"><span class="big">${g.crystals[i]?'✦':'◇'}</span>${n.toUpperCase()}</div>`).join('')}</div></div><div class="info-card"><h3>Treinador(a)</h3><p>Moedas: ${g.coins} · Criaturas: ${g.team.length} · Passos: ${g.steps||0}</p></div>`}
 }
 function openMenu(g){game=g;tab='team';document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));renderMenu(g);show('#menuScreen')}
 function openShop(g,buy){$('#shopCoins').textContent=g.coins;$('#shopList').innerHTML=D.items.map(it=>`<div class="item-row"><div class="item-ico">${it.icon}</div><div class="item-main"><div class="item-name">${it.name}</div><div class="item-desc">${it.desc}</div></div><button class="buy-btn" data-buy="${it.id}">${it.price} ◉</button></div>`).join('');$('#shopList').querySelectorAll('[data-buy]').forEach(b=>{b.disabled=g.coins<D.items.find(i=>i.id===b.dataset.buy).price;b.onclick=()=>{buy(b.dataset.buy);openShop(g,buy)}});show('#shopScreen')}
 function setup(g){$('#dialogue').addEventListener('click',advance);$('#dlgPortrait canvas').width=96;$('#dlgPortrait canvas').height=96;W.NevSprites.draw($('#dlgPortrait canvas'),'lumito');$('#btnPause').onclick=()=>openMenu(g());$('#btnMenuM').onclick=()=>openMenu(g());$('#btnAction').onclick=()=>W.NevWorld.interact();$('#btnNew').onclick=()=>g().startNew();$('#btnContinue').onclick=()=>g().continueGame();$('#btnHow').onclick=()=>say('Como jogar',['Use o direcional para explorar a vila e os campos. Aproxime-se das pessoas e toque A para conversar.','Na batalha, escolha um movimento. Poções e orbes podem ser usados na Bolsa.'],()=>{});$('#btnSave').onclick=()=>{g().save();toast('Jornada salva neste aparelho.')};$('#btnHelp').onclick=()=>say('Controles',['Direcional/toque na tela: mover. A: conversar/interagir. Menu: time, bolsa e jornada. No teclado: WASD ou setas, Espaço/Enter para ação.']);$('#btnQuit').onclick=()=>{hide('#menuScreen');g().toTitle()};document.querySelectorAll('[data-close-menu]').forEach(b=>b.onclick=()=>hide('#menuScreen'));document.querySelectorAll('[data-close-shop]').forEach(b=>b.onclick=()=>hide('#shopScreen'));document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));renderMenu(g())})}
 const W=window;window.NevUI={setup,say,choices,advance,toast,hide,show,openMenu,openShop,renderMenu};
})();

(function(){const D=window.NevData,$=s=>document.querySelector(s);let game=null,enemy=null,active=false,busy=false;
 function start(g,id,level=3,boss=false){game=g;let sp=D.species[id]||D.species.gotinha;enemy={id,level,maxHp:boss?52:22+level*4,hp:boss?52:22+level*4,boss};active=true;busy=true;$('#enemyWrap').classList.remove('faint');$('#playerWrap').classList.remove('faint');$('#battleScreen').classList.remove('hidden');$('#hud').classList.add('hidden');document.getElementById('world').classList.add('hidden');render();W.NevSprites.draw($('#enemySprite'),id);W.NevSprites.draw($('#playerSprite'),game.team[game.lead].id);setMsg(`${boss?'Um guardião':'Uma criatura selvagem'} apareceu!`);setTimeout(()=>{busy=false;actions()},550)}
 function render(){let m=game.team[game.lead],s=D.species[enemy.id];$('#enemyName').textContent=s.name;$('#enemyLevel').textContent='Nv. '+enemy.level;$('#enemyHpText').textContent=`${enemy.hp}/${enemy.maxHp}`;$('#enemyHp').style.width=(enemy.hp/enemy.maxHp*100)+'%';$('#bpName').textContent=D.species[m.id].name;$('#bpLevel').textContent='Nv. '+m.level;$('#playerHpText').textContent=`${m.hp}/${m.maxHp}`;$('#playerHp').style.width=(m.hp/m.maxHp*100)+'%';$('#enemyStatus').className='status-chip';$('#playerStatus').className='status-chip';W.NevSprites.draw($('#enemySprite'),enemy.id);W.NevSprites.draw($('#playerSprite'),m.id)}
