(function(){
  const game = window.NevGame.createGame();
  window.gameState = game;
  window.NevGame.init();
  document.getElementById('btnContinue').classList.toggle('hidden', !localStorage.getItem('nevoa-save'));
  const titleCanvas = document.getElementById('titleCanvas');
  const canvas = titleCanvas;
  if (canvas) {
    const ctx = canvas.getContext('2d');
    function frame(){
      const w = canvas.width = innerWidth;
      const h = canvas.height = innerHeight;
      ctx.clearRect(0,0,w,h);
      const g = ctx.createRadialGradient(w*.5,h*.28,60,w*.5,h*.5,500); g.addColorStop(0,'rgba(120,120,255,.55)'); g.addColorStop(1,'rgba(20,15,32,0)'); ctx.fillStyle=g; ctx.fillRect(0,0,w,h);
      for(let i=0;i<48;i++){
        const x=(i*137) % w; const y=(i*91 + performance.now()*0.02)%h; ctx.fillStyle=`rgba(255,255,255,${0.15 + i%6*.08})`; ctx.fillRect(x,y,2,2);
      }
      ctx.fillStyle='#8fd3b3'; ctx.beginPath(); ctx.ellipse(w*.5,h*.92,320,90,0,0,Math.PI*2); ctx.fill();
      requestAnimationFrame(frame);
    }
    frame();
  }
  window.NevSprites.draw(document.getElementById('logoCreature'),'lumito',1.14);
})();

